from collections.abc import Mapping
from dataclasses import dataclass


@dataclass(frozen=True)
class Route:
    path: str
    handler: object
    name: str


def compile_routes(specs, assets=None):
    try:
        entries = list(specs)
    except TypeError:
        raise ValueError("specs must be iterable") from None
    result = []
    paths = set()
    names = set()
    for spec in sorted(entries, key=lambda item: item[0]):
        if not isinstance(spec, tuple) or len(spec) != 3:
            raise ValueError("invalid route specification")
        path, handler, name = spec
        if not isinstance(path, str) or not path or not callable(handler):
            raise ValueError("invalid route")
        if not isinstance(name, str) or not name:
            raise ValueError("invalid route name")
        if path in paths or name in names:
            raise ValueError("duplicate route")
        paths.add(path)
        names.add(name)
        result.append(Route(path, handler, name))
    if assets is None:
        assets = {}
    if not isinstance(assets, Mapping):
        raise ValueError("assets must be a mapping")
    for path in sorted(assets):
        handler = assets[path]
        name = "asset:" + path if isinstance(path, str) else ""
        if not isinstance(path, str) or not path or not callable(handler):
            raise ValueError("invalid asset route")
        if path in paths or name in names:
            raise ValueError("duplicate route")
        paths.add(path)
        names.add(name)
        result.append(Route(path, handler, name))
    return result

